// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(address actor, uint256 amount1, uint256 amount2) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount1 = bound(amount1, 1 ether, 100 ether);
        amount2 = bound(amount2, 1 ether, 100 ether);

        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
        c.Deposit{value: amount1}();

        vm.prank(actor);
        c.Deposit{value: amount2}();

        assertTrue(c.balances(actor) == amount1 + amount2);
    }
}
